// Messages in MailMate-labelled threads that I didn't send and this workflow hasn't seen yet: one
// alert each. The first run only remembers what's there, so old replies don't all arrive at once.
// (Workflow static data is kept only for the published workflow, not for test runs in the editor.)
const INCLUDE_SNIPPET = true;    // false: an alert names only the sender and the subject
const state = $getWorkflowStaticData('global');
const first = !Array.isArray(state.seen);
const seen = new Set(state.seen || []);
const NL = String.fromCharCode(10);
const header = (m, name) => {
  for (const h of (m.payload?.headers || [])) if (String(h.name).toLowerCase() === name) return String(h.value || '');
  return '';
};
const plain = s => String(s || '').split('&#39;').join("'").split('&quot;').join('"').split('&lt;').join('<')
  .split('&gt;').join('>').split('&amp;').join('&');
const alerts = [];
for (const item of $input.all()) {
  const t = item.json;
  if (!t || !Array.isArray(t.messages)) continue;
  for (const m of t.messages) {
    if (seen.has(m.id)) continue;
    seen.add(m.id);
    if (first || (m.labelIds || []).includes('SENT')) continue;
    const from = header(m, 'from');
    const bounce = /mailer-daemon|postmaster/i.test(from);
    const lines = [(bounce ? 'Bounce' : 'New reply') + ' (MailMate)', 'From: ' + from, 'Subject: ' + header(m, 'subject')];
    if (INCLUDE_SNIPPET && m.snippet) lines.push('', plain(m.snippet).slice(0, 300));
    lines.push('', bounce ? 'The address is dead: the next sync puts it on the do-not-contact list.'
                          : 'Open MailMate -> 6 Replies -> Reply desk to answer it.');
    alerts.push({ json: { text: lines.join(NL) } });
  }
}
state.seen = Array.from(seen).slice(-2000);
return alerts;
